// installCmd represents the install command
var installCmd = &cobra.Command{
	Example: "  tptctl spring-boot install",
	Long:    "Install the SpringBoot module to an existing Threeport control plane",
	PreRun:  tptctl_cmd.CommandPreRunFunc,
	Run: func(cmd *cobra.Command, args []string) {
		apiClient, _, apiEndpoint, requestedControlPlane := tptctl_cmd.GetClientContext(cmd)

		// get Kubernetes runtime instance for control plane
		queryString := "ThreeportControlPlaneHost=true"
		kubernetesRuntimeInstances, err := client.GetKubernetesRuntimeInstancesByQueryString(
			apiClient,
			apiEndpoint,
			queryString,
		)
		if err != nil {
			cli.Error("failed to get kubernetes runtime instances", err)
			os.Exit(1)
		}
		if len(*kubernetesRuntimeInstances) != 1 {
			cli.Error(fmt.Sprintf("found %d k8s runtime instances", len(*kubernetesRuntimeInstances)), err)
			os.Exit(1)
		}
		kubeRuntimes := *kubernetesRuntimeInstances

		// get threeport config
		threeportConfig, _, err := cli.GetThreeportConfig(requestedControlPlane)
		if err != nil {
			cli.Error("failed to get threeport config", err)
			os.Exit(1)
		}

		// get encryption key
		encryptionKey, err := threeportConfig.GetThreeportEncryptionKey(requestedControlPlane)
		if err != nil {
			cli.Error("failed to get Threeport API encryption key", err)
			os.Exit(1)
		}

		// determine if auth is enabled on control plane
		authEnabled, err := threeportConfig.GetThreeportAuthEnabled(requestedControlPlane)
		if err != nil {
			cli.Error("failed to determine if auth is enabled", err)
			os.Exit(1)
		}

		// get Kubernetes client
		dynamicInterface, restMapper, err := kube.GetClient(
			&kubeRuntimes[0],
			false,
			apiClient,
			apiEndpoint,
			encryptionKey,
		)
		if err != nil {
			cli.Error("failed to get Kube client", err)
			os.Exit(1)
		}

		// create installer
		inst := installer.NewInstaller(dynamicInterface, restMapper)
		inst.AuthEnabled = authEnabled
		inst.ControlPlaneImageRepo = controlPlaneImageRepo
		inst.ControlPlaneImageTag = controlPlaneImageTag
		inst.Debug = debug
		inst.ApiClient = apiClient
		inst.ApiEndpoint = apiEndpoint
		inst.ImagePullSecretFile = imagePullSecretFile

		// install extension module
		if err := inst.InstallSpringBootModule(); err != nil {
			cli.Error("failed to install SpringBoot module", err)
			os.Exit(1)
		}

		cli.Complete("SpringBoot module installed")
	},
	Short:        "Install the SpringBoot module to an existing Threeport control plane",
	SilenceUsage: true,
	Use:          "install",
}

